const hook = $('Webhook (analyze)').first().json;

const raw =
  typeof hook.imageUrl === 'string' && hook.imageUrl.trim() !== '' ? hook.imageUrl
  : (typeof hook.base64Image === 'string' && hook.base64Image.trim() !== '' ? hook.base64Image
  : '');
const dataUrl = raw.startsWith('data:') ? raw : '';

// A stable per-scan session id for the memory node. The app sends scanId for
// chat; for scans we derive one from the image if absent so memory stays keyed
// consistently per plant.
const scanId = typeof hook.scanId === 'string' && hook.scanId.trim() !== ''
  ? hook.scanId
  : 'scan-' + (typeof hook.imageUrl === 'string' ? hook.imageUrl : raw).slice(0, 64);

return [{ json: {
  ...hook,
  scanId,
  url: dataUrl ? '' : raw,
  dataUrl,
  imageUrl: raw
} }];

const resolved = $('Resolve image').first().json;
const prepared = $('Prepare agent input').first().json;

// If we already fetched the image as binary via the HTTP node, keep it.
const input = $input.all()[0];
const hasBinary = !!(input && input.binary && Object.keys(input.binary).length > 0);

if (hasBinary) {
  return [{ json: prepared, binary: input.binary }];
}

// Otherwise the payload was a base64 data: URL. Convert it to a binary image
// so the AI Agent's passthroughBinaryImages can forward it to the model.
if (resolved.dataUrl) {
  const match = /^data:([^;]+);base64,(.+)$/.exec(resolved.dataUrl);
  if (match) {
    const mime = match[1] || 'image/jpeg';
    const b64 = match[2];
    return [{ json: prepared, binary: { data: {
      data: b64,
      mimeType: mime,
      fileName: prepared.imageUrl.split('/').pop() || 'plant.jpg'
    } } }];
  }
}

throw new Error('No image received. imageUrl: ' + (resolved.imageUrl || '(none)') + ' | base64Image: ' + (resolved.dataUrl ? '(data URL)' : '(none)'));

const source = $('Merge').first().json;
const resolved = $('Resolve image').first().json;

const hasWeather = source && source.main &&
  (source.main.temp !== undefined || source.main.humidity !== undefined);
const temp = hasWeather ? source.main.temp : 'N/A';
const humidity = hasWeather ? source.main.humidity : 'N/A';

const chatInput =
  'Analyze this plant photo. Identify the species and assess its health using the schema provided. ' +
  'Environmental context — Temperature: ' + temp + '°C, Humidity: ' + humidity + '%. ' +
  'If no temperature/humidity is provided, reason from the image alone and leave the environmental_impact as a general statement.';

return [{ json: {
  chatInput,
  temp,
  humidity,
  scanId: resolved.scanId,
  imageUrl: resolved.imageUrl,
  lat: resolved.lat,
  lng: resolved.lng
} }];

const item = $input.all()[0].json;
const agentCtx = $('Prepare agent input').first().json;
const wrapped = item.output || item.json || item;
const parsed = (wrapped && wrapped.output && typeof wrapped.output === 'object') ? wrapped.output : wrapped;

return [{ json: {
  analysis: parsed,
  imageUrl: agentCtx.imageUrl || '',
  temp: agentCtx.temp,
  humidity: agentCtx.humidity,
  scanId: agentCtx.scanId || '',
  created_at: new Date().toISOString()
} }];
